CREATE TABLE en1991_thermal_section(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, deck_type INTEGER NOT NULL CHECK(deck_type>=0 AND deck_type<=255), surfacing INTEGER NOT NULL CHECK(surfacing>=0 AND surfacing<=255), length REAL, depth REAL, alpha_micro REAL, assumed_range REAL, length_ieee754_bits INTEGER NOT NULL, length_ieee754_class TEXT NOT NULL, depth_ieee754_bits INTEGER NOT NULL, depth_ieee754_class TEXT NOT NULL, alpha_micro_ieee754_bits INTEGER NOT NULL, alpha_micro_ieee754_class TEXT NOT NULL, assumed_range_ieee754_bits INTEGER NOT NULL, assumed_range_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_case(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, label_en TEXT NOT NULL, label_de TEXT NOT NULL, entry_id TEXT NOT NULL);
CREATE TABLE en1991_case_number(id INTEGER PRIMARY KEY, case_id INTEGER NOT NULL REFERENCES en1991_case(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, value REAL, value_ieee754_bits INTEGER NOT NULL, value_ieee754_class TEXT NOT NULL);
