CREATE TABLE en1991_construction_load(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, stage TEXT NOT NULL, kind INTEGER NOT NULL CHECK(kind>=0 AND kind<=255), magnitude REAL, magnitude_ieee754_bits INTEGER NOT NULL, magnitude_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_falling_load(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, mass REAL, drop_height REAL, stopping_distance REAL, x REAL, y REAL, assumed_force REAL, mass_ieee754_bits INTEGER NOT NULL, mass_ieee754_class TEXT NOT NULL, drop_height_ieee754_bits INTEGER NOT NULL, drop_height_ieee754_class TEXT NOT NULL, stopping_distance_ieee754_bits INTEGER NOT NULL, stopping_distance_ieee754_class TEXT NOT NULL, x_ieee754_bits INTEGER NOT NULL, x_ieee754_class TEXT NOT NULL, y_ieee754_bits INTEGER NOT NULL, y_ieee754_class TEXT NOT NULL, assumed_force_ieee754_bits INTEGER NOT NULL, assumed_force_ieee754_class TEXT NOT NULL);
