CREATE TABLE en1991_bulk_solid(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, internal_friction REAL, internal_friction_ieee754_bits INTEGER NOT NULL, internal_friction_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_rotating_machine(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, mass REAL, eccentricity REAL, frequency REAL, mass_ieee754_bits INTEGER NOT NULL, mass_ieee754_class TEXT NOT NULL, eccentricity_ieee754_bits INTEGER NOT NULL, eccentricity_ieee754_class TEXT NOT NULL, frequency_ieee754_bits INTEGER NOT NULL, frequency_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_fatigue_model(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, model TEXT NOT NULL, lane INTEGER NOT NULL CHECK(lane>=0 AND lane<=255), assumed_axle_load REAL, assumed_udl REAL, assumed_axle_load_ieee754_bits INTEGER NOT NULL, assumed_axle_load_ieee754_class TEXT NOT NULL, assumed_udl_ieee754_bits INTEGER NOT NULL, assumed_udl_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_support_collision(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, location TEXT NOT NULL, assumed_force_x REAL, assumed_force_y REAL, height REAL, position_x REAL, assumed_force_x_ieee754_bits INTEGER NOT NULL, assumed_force_x_ieee754_class TEXT NOT NULL, assumed_force_y_ieee754_bits INTEGER NOT NULL, assumed_force_y_ieee754_class TEXT NOT NULL, height_ieee754_bits INTEGER NOT NULL, height_ieee754_class TEXT NOT NULL, position_x_ieee754_bits INTEGER NOT NULL, position_x_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_local_fire(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, fire_diameter REAL, heat_release_rate REAL, ceiling_height REAL, horizontal_distance REAL, assumed_flux REAL, fire_diameter_ieee754_bits INTEGER NOT NULL, fire_diameter_ieee754_class TEXT NOT NULL, heat_release_rate_ieee754_bits INTEGER NOT NULL, heat_release_rate_ieee754_class TEXT NOT NULL, ceiling_height_ieee754_bits INTEGER NOT NULL, ceiling_height_ieee754_class TEXT NOT NULL, horizontal_distance_ieee754_bits INTEGER NOT NULL, horizontal_distance_ieee754_class TEXT NOT NULL, assumed_flux_ieee754_bits INTEGER NOT NULL, assumed_flux_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_snow_guard(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, roof_id TEXT NOT NULL, slope_length REAL, assumed_force REAL, slope_length_ieee754_bits INTEGER NOT NULL, slope_length_ieee754_class TEXT NOT NULL, assumed_force_ieee754_bits INTEGER NOT NULL, assumed_force_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_rail_derailment(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, situation TEXT NOT NULL, assumed_line_load REAL, loaded_length REAL, offset REAL, assumed_line_load_ieee754_bits INTEGER NOT NULL, assumed_line_load_ieee754_class TEXT NOT NULL, loaded_length_ieee754_bits INTEGER NOT NULL, loaded_length_ieee754_class TEXT NOT NULL, offset_ieee754_bits INTEGER NOT NULL, offset_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_rail_load_group(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, load_group TEXT NOT NULL, factor_vertical REAL, factor_longitudinal REAL, factor_lateral REAL, assumed_axle_load REAL, assumed_udl REAL, assumed_longitudinal REAL, assumed_lateral REAL, factor_vertical_ieee754_bits INTEGER NOT NULL, factor_vertical_ieee754_class TEXT NOT NULL, factor_longitudinal_ieee754_bits INTEGER NOT NULL, factor_longitudinal_ieee754_class TEXT NOT NULL, factor_lateral_ieee754_bits INTEGER NOT NULL, factor_lateral_ieee754_class TEXT NOT NULL, assumed_axle_load_ieee754_bits INTEGER NOT NULL, assumed_axle_load_ieee754_class TEXT NOT NULL, assumed_udl_ieee754_bits INTEGER NOT NULL, assumed_udl_ieee754_class TEXT NOT NULL, assumed_longitudinal_ieee754_bits INTEGER NOT NULL, assumed_longitudinal_ieee754_class TEXT NOT NULL, assumed_lateral_ieee754_bits INTEGER NOT NULL, assumed_lateral_ieee754_class TEXT NOT NULL);
CREATE TABLE en1991_dust_explosion(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1991_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, kst REAL, p_max REAL, volume REAL, vent_area REAL, static_opening_pressure REAL, design_pressure REAL, kst_ieee754_bits INTEGER NOT NULL, kst_ieee754_class TEXT NOT NULL, p_max_ieee754_bits INTEGER NOT NULL, p_max_ieee754_class TEXT NOT NULL, volume_ieee754_bits INTEGER NOT NULL, volume_ieee754_class TEXT NOT NULL, vent_area_ieee754_bits INTEGER NOT NULL, vent_area_ieee754_class TEXT NOT NULL, static_opening_pressure_ieee754_bits INTEGER NOT NULL, static_opening_pressure_ieee754_class TEXT NOT NULL, design_pressure_ieee754_bits INTEGER NOT NULL, design_pressure_ieee754_class TEXT NOT NULL);
